// Columnas que la tabla todavía no tiene. Se llena cuando un guardado tuvo que dejar algún
// dato afuera, para poder mostrar en pantalla el SQL que falta.
var columnasFaltantes=[];
var SQL_COLUMNAS={
  retiro_caja:"alter table cierres_caja add column if not exists retiro_caja numeric default 0;",
  retiro_caja_nota:"alter table cierres_caja add column if not exists retiro_caja_nota text;",
  mp_transferencia:"alter table cierres_caja add column if not exists mp_transferencia numeric default 0;",
  mp_qr:"alter table cierres_caja add column if not exists mp_qr numeric default 0;",
  mp_debito:"alter table cierres_caja add column if not exists mp_debito numeric default 0;",
  mp_credito:"alter table cierres_caja add column if not exists mp_credito numeric default 0;",
  pat_transferencia:"alter table cierres_caja add column if not exists pat_transferencia numeric default 0;",
  pat_qr:"alter table cierres_caja add column if not exists pat_qr numeric default 0;",
  pat_debito:"alter table cierres_caja add column if not exists pat_debito numeric default 0;",
  pat_credito:"alter table cierres_caja add column if not exists pat_credito numeric default 0;"
};
function sqlDeFaltantes(){
  return columnasFaltantes.map(function(k){return SQL_COLUMNAS[k]||("-- falta la columna "+k);}).join("\n");
}

async function sbSaveCierre(cierre) {
  try {
    var h = {...SH, "Prefer": "resolution=merge-duplicates,return=representation"};
    var cuerpo = {...cierre};
    var faltantes = [];
    // Si a la tabla le falta alguna columna nueva, Postgrest la nombra en el error. Se saca
    // ese campo y se reintenta: el cierre se guarda igual y después se avisa qué quedó
    // afuera, en vez de perder la carga entera por un ALTER TABLE pendiente.
    for (var intento = 0; intento < 8; intento++) {
      var r = await fetch(SURL + "/rest/v1/cierres_caja", { method: "POST", headers: h, body: JSON.stringify(cuerpo) });
      if (r.ok) {
        if (faltantes.length > 0) {
          columnasFaltantes = faltantes.slice();
          var conDato = faltantes.filter(function(k){ return parseFloat(cierre[k]||0) > 0 || (typeof cierre[k] === "string" && cierre[k] !== ""); });
          if (conDato.length > 0) alert("El cierre se guardó, pero estos datos no: " + conDato.join(", ") + ". Faltan esas columnas en la tabla cierres_caja — corré el ALTER TABLE del README.");
        }
        return true;
      }
      var err = await r.text();
      var falta = null;
      Object.keys(cuerpo).forEach(function(k){
        if (falta) return;
        if (k === "id" || k === "local" || k === "fecha") return;
        if (new RegExp("'" + k + "'|\\b" + k + "\\b").test(err) && /column|schema cache|PGRST204/i.test(err)) falta = k;
      });
      if (!falta) { alert("Error al guardar: " + err); return false; }
      faltantes.push(falta);
      delete cuerpo[falta];
    }
    alert("No se pudo guardar el cierre: faltan demasiadas columnas en la tabla cierres_caja. Corré el ALTER TABLE del README.");
    return false;
  } catch(e) { alert("Error de conexión: " + e.message); return false; }
}

async function sbDeleteCierre(id) {
  try {
    await fetch(SURL + "/rest/v1/cierres_caja?id=eq." + id, { method: "DELETE", headers: SH });
  } catch(e) {}
}

// ─── VENCIMIENTOS SUPABASE ────────────────────────────────────────────────────
// Un jsonb puede volver como texto si la columna se creó como text. Se parsea igual, así
// un plan con sus cuotas no se ve vacío por culpa del tipo de la columna.
function comoLista(v){
  if(Array.isArray(v))return v;
  if(typeof v==="string"&&v.trim()){ try{ var d=JSON.parse(v); return Array.isArray(d)?d:[]; }catch(e){ return []; } }
  return [];
}
async function sbLoadVencimientos() {
  try {
    var r = await fetch(SURL + "/rest/v1/vencimientos?order=created_at.desc", { headers: {...SH,"Cache-Control":"no-cache","Pragma":"no-cache"} });
    var d = await r.json();
    if(!Array.isArray(d))return [];
    return d.map(function(v){ return {...v, cuotas_plan:comoLista(v.cuotas_plan), pagos:comoLista(v.pagos)}; });
  } catch(e) { return []; }
}
// Qué columnas nuevas le faltan a la tabla, preguntando antes de que alguien intente
// guardar: Postgrest contesta 400 nombrando la primera que no existe, así que se la saca y
// se vuelve a preguntar. Si está todo, es una sola consulta que no trae ninguna fila.
// Todas las columnas que la app escribe, no sólo las nuevas: si a la tabla le falta
// cualquiera —hasta una de las de siempre, como subramo— se avisa antes de que alguien
// intente guardar y se quede sin entender por qué no anda.
var COLUMNAS_NUEVAS_VENC=["local","concepto","area","subramo","monto","recurrente","dia","fecha","activo","notas","pagos","usuario",
  "grupo","referencia","cuotas","cuotas_previas","tipo","nro_plan","cuotas_plan","cuit","debito_cuenta","debito_cbu","caduca_en",
  "periodo","nro_asociado","entidad","tipo_prestamo","fecha_otorgamiento","tna","deuda_actual","forma_pago",
  "monto_inicial","nro_credito"];
async function sbColumnasFaltantesVencimientos() {
  var pide = COLUMNAS_NUEVAS_VENC.slice();
  var faltan = [];
  try {
    for (var i = 0; i < COLUMNAS_NUEVAS_VENC.length + 1 && pide.length > 0; i++) {
      var r = await fetch(SURL + "/rest/v1/vencimientos?select=" + pide.join(",") + "&limit=1", { headers: SH });
      if (r.ok) return faltan;
      var err = await r.text();
      var falta = columnaFaltante(err);
      if (!falta || pide.indexOf(falta) < 0) return faltan;
      faltan.push(falta);
      pide = pide.filter(function(k){ return k !== falta; });
    }
  } catch(e) {}
  return faltan;
}
// El ALTER TABLE de cada columna nueva, para poder mostrarlo en pantalla en vez de mandar
// a buscarlo al README.
var SQL_VENCIMIENTOS={
  grupo:"alter table vencimientos add column if not exists grupo          text default 'otros';",
  referencia:"alter table vencimientos add column if not exists referencia     text;",
  cuotas:"alter table vencimientos add column if not exists cuotas         int default 0;",
  cuotas_previas:"alter table vencimientos add column if not exists cuotas_previas int default 0;",
  tipo:"alter table vencimientos add column if not exists tipo           text default 'simple';",
  nro_plan:"alter table vencimientos add column if not exists nro_plan       text;",
  cuotas_plan:"alter table vencimientos add column if not exists cuotas_plan    jsonb default '[]'::jsonb;",
  cuit:"alter table vencimientos add column if not exists cuit           text;",
  debito_cuenta:"alter table vencimientos add column if not exists debito_cuenta  text;",
  debito_cbu:"alter table vencimientos add column if not exists debito_cbu     text;",
  caduca_en:"alter table vencimientos add column if not exists caduca_en      int default 3;",
  periodo:"alter table vencimientos add column if not exists periodo        text;",
  nro_asociado:"alter table vencimientos add column if not exists nro_asociado   text;",
  entidad:"alter table vencimientos add column if not exists entidad        text;",
  tipo_prestamo:"alter table vencimientos add column if not exists tipo_prestamo  text;",
  fecha_otorgamiento:"alter table vencimientos add column if not exists fecha_otorgamiento date;",
  tna:"alter table vencimientos add column if not exists tna            text;",
  deuda_actual:"alter table vencimientos add column if not exists deuda_actual   numeric default 0;",
  forma_pago:"alter table vencimientos add column if not exists forma_pago     text;",
  monto_inicial:"alter table vencimientos add column if not exists monto_inicial  numeric default 0;",
  nro_credito:"alter table vencimientos add column if not exists nro_credito    text;",
  local:"alter table vencimientos add column if not exists local          text;",
  concepto:"alter table vencimientos add column if not exists concepto       text;",
  area:"alter table vencimientos add column if not exists area           text;",
  subramo:"alter table vencimientos add column if not exists subramo        text;",
  monto:"alter table vencimientos add column if not exists monto          numeric default 0;",
  recurrente:"alter table vencimientos add column if not exists recurrente     boolean default true;",
  dia:"alter table vencimientos add column if not exists dia            int;",
  fecha:"alter table vencimientos add column if not exists fecha          date;",
  activo:"alter table vencimientos add column if not exists activo         boolean default true;",
  notas:"alter table vencimientos add column if not exists notas          text;",
  pagos:"alter table vencimientos add column if not exists pagos          jsonb default '[]'::jsonb;",
  usuario:"alter table vencimientos add column if not exists usuario        text;"
};
// Un plan sin estas dos columnas no es un plan: guardarlo igual dejaría un registro que no
// se puede ni leer ni pagar. Se corta y se dice qué correr.
var COLUMNAS_PLAN=["tipo","cuotas_plan"];
// Postgrest nombra la columna que falta de dos maneras según de dónde venga el error: por
// el schema cache ("Could not find the 'cuit' column") o por Postgres mismo
// ("column \"cuit\" of relation \"vencimientos\" does not exist"). Las dos dicen lo mismo.
function columnaFaltante(err){
  // Postgres manda el error adentro de un JSON, así que las comillas del nombre vienen
  // escapadas: column \"cuit\" of relation \"vencimientos\". Se sacan las barras primero.
  var t=String(err||"").replace(/\\/g,"");
  var m=/Could not find the '([^']+)' column/i.exec(t)
     ||/column "?([a-z0-9_]+)"? of relation/i.exec(t)
     ||/column "?(?:vencimientos\.)?([a-z0-9_]+)"? does not exist/i.exec(t);
  return m?m[1]:null;
}
// Que falte la tabla entera es otra cosa que una columna, y se confunden fácil: el error de
// columna también nombra la tabla y también dice "does not exist". Por eso se mira primero
// si hay una columna adentro del mensaje.
function faltaLaTabla(err){
  if(columnaFaltante(err))return false;
  var t=String(err||"").replace(/\\/g,"");
  return /PGRST205/.test(t)||/relation "?(public\.)?vencimientos"? does not exist/i.test(t)||/Could not find the table/i.test(t);
}
// Un guardado de prueba de punta a punta, para ver qué contesta la tabla de verdad cuando
// algo no anda. Prueba las dos formas que tiene un vencimiento —el suelto recurrente y el
// plan con sus cuotas—, porque no mandan los mismos campos y puede fallar sólo una: escribe,
// lee de vuelta, comprueba que los campos hayan llegado enteros y borra.
async function sbProbarVencimiento(prueba, campos, titulo) {
  var lineas = [];
  try {
    var h = {...SH, "Prefer": "resolution=merge-duplicates,return=representation"};
    var r = await fetch(SURL + "/rest/v1/vencimientos", { method:"POST", headers:h, body:JSON.stringify(prueba) });
    var txt = await r.text();
    lineas.push(titulo + " → HTTP " + r.status + (r.ok ? "  OK" : "  FALLÓ"));
    if (!r.ok) {
      lineas.push("   " + txt.slice(0,400));
      var c = columnaFaltante(txt);
      if (c) lineas.push("   → falta la columna \"" + c + "\": " + (SQL_VENCIMIENTOS[c]||"alter table vencimientos add column if not exists "+c+" text;"));
      if (/row-level security|42501/i.test(txt)) lineas.push("   → la tabla tiene RLS activado: alter table vencimientos disable row level security;");
      return lineas;
    }
    var r2 = await fetch(SURL + "/rest/v1/vencimientos?id=eq." + prueba.id, { headers:{...SH,"Cache-Control":"no-cache"} });
    var d2 = await r2.json();
    var v = Array.isArray(d2) ? d2[0] : null;
    if (!v) { lineas.push("   se guardó pero no volvió al leerlo (HTTP " + r2.status + ")"); }
    else {
      campos.forEach(function(c){
        var val = v[c.k];
        var ok = c.ok(val, v);
        lineas.push("   " + (c.k + "            ").slice(0,13) + "= " + JSON.stringify(val===undefined?null:val) + (ok ? "  OK" : "  MAL (" + c.esp + ")"));
      });
    }
    var r3 = await fetch(SURL + "/rest/v1/vencimientos?id=eq." + prueba.id, { method:"DELETE", headers:SH });
    if (!r3.ok) lineas.push("   la prueba no se pudo borrar (HTTP " + r3.status + "), borrala a mano");
  } catch(e) {
    lineas.push(titulo + " → error de conexión: " + e.message);
  }
  return lineas;
}
async function sbDiagnosticoVencimientos() {
  // Cada prueba manda exactamente los mismos campos que su formulario: el suelto lleva
  // subramo y el plan no, y justamente esa diferencia puede ser la que falle.
  var base = {
    grupo:"servicios", local:"l1", cuit:"", area:"Servicios",
    concepto:"PRUEBA de guardado — se borra sola", notas:"", referencia:"TEST",
    debito_cuenta:"Transferencia - Provincia Personas", debito_cbu:"prueba.alias",
    activo:false, pagos:[], usuario:"diagnostico", created_at:new Date().toISOString()
  };
  var suelto = {...base,
    id:"venc_test_"+String(Date.now()), subramo:"",
    monto:1, recurrente:true, dia:10, fecha:null, cuotas:0, cuotas_previas:0
  };
  var plan = {...base,
    id:"plan_test_"+String(Date.now()+1),
    tipo:"plan", grupo:"afip", local:"l4", cuit:"c2", area:"Administrativo",
    nro_plan:"TEST", monto:1, recurrente:false, dia:null, fecha:null,
    cuotas:2, cuotas_previas:0,
    cuotas_plan:[{nro:0,vence:"2026-01-05",monto:1},{nro:1,vence:"2026-02-05",monto:1}]
  };
  var l1 = await sbProbarVencimiento(suelto, [
    {k:"grupo",        esp:'tendría que ser "servicios"', ok:function(x){return x==="servicios";}},
    {k:"recurrente",   esp:"tendría que ser true",        ok:function(x){return x===true;}},
    {k:"dia",          esp:"tendría que ser 10",          ok:function(x){return Number(x)===10;}},
    {k:"subramo",      esp:"la columna no guarda",        ok:function(x){return x!==undefined&&x!==null;}},
    {k:"debito_cuenta",esp:"la columna no guarda",        ok:function(x){return !!x;}},
    {k:"debito_cbu",   esp:"la columna no guarda",        ok:function(x){return !!x;}}
  ], "1) Vencimiento suelto (+ Nuevo)");
  var l2 = await sbProbarVencimiento(plan, [
    {k:"tipo",         esp:'tendría que ser "plan"',      ok:function(x){return x==="plan";}},
    {k:"cuotas_plan",  esp:"tendrían que ser 2 cuotas",   ok:function(x){return comoLista(x).length===2;}},
    {k:"nro_plan",     esp:"la columna no guarda",        ok:function(x){return !!x;}},
    {k:"cuit",         esp:"la columna no guarda",        ok:function(x){return !!x;}}
  ], "2) Plan de pago (+ Plan de pago)");
  return l1.concat([""]).concat(l2).join("\n");
}
async function sbSaveVencimiento(v) {
  try {
    var h = {...SH, "Prefer": "resolution=merge-duplicates,return=representation"};
    var cuerpo = {...v};
    var faltantes = [];
    // Si a la tabla le falta una columna nueva, se saca ese campo y se reintenta: el
    // vencimiento se guarda igual y después se avisa qué quedó afuera, en vez de perder la
    // carga por un alter table pendiente.
    for (var intento = 0; intento < 10; intento++) {
      var r = await fetch(SURL + "/rest/v1/vencimientos", { method: "POST", headers: h, body: JSON.stringify(cuerpo) });
      if (r.ok) {
        if (faltantes.length > 0) {
          alert("Se guardó, pero estos datos no: "+faltantes.join(", ")+".\n\nFaltan esas columnas en la tabla vencimientos. Corré esto en Supabase → SQL Editor:\n\n"
            +faltantes.map(function(k){return SQL_VENCIMIENTOS[k]||("-- falta la columna "+k);}).join("\n"));
        }
        return true;
      }
      var err = await r.text();
      if (faltaLaTabla(err)) {
        alert("Falta la tabla \"vencimientos\" en Supabase. Corré el SQL del README.");
        return false;
      }
      // El RLS prendido rechaza toda escritura con la clave anónima: no es un problema de
      // columnas y el mensaje crudo no se entiende, así que se dice qué correr.
      if (/row-level security|42501/i.test(err)) {
        alert("La tabla vencimientos tiene la seguridad por filas (RLS) activada, así que Supabase rechaza todo lo que se quiera guardar.\n\nCorré esto en Supabase → SQL Editor:\n\nalter table vencimientos disable row level security;");
        return false;
      }
      var falta = columnaFaltante(err);
      if (!falta || falta === "id" || falta === "concepto") { alert("Error al guardar el vencimiento: " + err); return false; }
      if (COLUMNAS_PLAN.indexOf(falta) >= 0 && tieneCuotas(v)) {
        alert("No se puede guardar el plan: a la tabla vencimientos le falta la columna \""+falta+"\".\n\nUn plan sin ella no se podría ni leer ni pagar, así que no se guarda a medias. Corré esto en Supabase → SQL Editor y volvé a cargarlo:\n\n"
          +COLUMNAS_PLAN.concat(["nro_plan","cuit"]).map(function(k){return SQL_VENCIMIENTOS[k];}).join("\n"));
        return false;
      }
      faltantes.push(falta);
      delete cuerpo[falta];
    }
    alert("No se pudo guardar el vencimiento: faltan demasiadas columnas en la tabla. Corré el SQL del README.");
    return false;
  } catch(e) { alert("Error de conexión: " + e.message); return false; }
}
